{"python":"import re
pdf='13048_2026_2178_MOESM1_ESM.pdf'
pages=['page3','page4','page5']

def meta(c,r,cidx):
    if isinstance(c,dict):
        return str(c.get('value','')).strip(), c.get('ref',f'{pdf}/{pages[0]}/R{r}C{cidx}')
    return str(c).strip(), f'{pdf}/{page}/R{r}C{cidx}'

def isnum(s):
    return re.fullmatch(r'>?\s*\d+(?:\.\d+)?', s or '') is not None

def fnum(s):
    return float(s.replace('>','').strip())

records=[]
debug=[]
for page in pages:
    src=tables[pdf][page]['rows']
    rows=[]
    for ri,raw in enumerate(src):
        rr=[]
        for ci,c in enumerate(raw):
            v,rf=meta(c,ri+1,ci+1)
            rr.append({'v':v,'ref':rf})
        rows.append(rr)
    for i,row in enumerate(rows):
        org_pos=[k for k,c in enumerate(row) if re.match(r'^Org-\d+',c['v'])]
        if not org_pos:
            continue
        k=org_pos[0]
        oid=row[k]['v']
        # Prospective clinical response is on the organoid row, except when drug data share that row.
        if any(c['v'].lower() in ('carboplatin','paclitaxel') for c in row):
            clin_rows=[rows[j] for j in range(i+1,min(len(rows),i+3))]
            clin=None
            for rr in clin_rows:
                labs=[c for c in rr if c['v'].lower() in ('sensitive','resistant')]
                if labs:
                    clin=labs[0]
                    break
        else:
            labs=[c for idx,c in enumerate(row) if idx>=k+2 and c['v'].lower() in ('sensitive','resistant')]
            clin=labs[0] if labs else None
        drug_refs={}
        drug_vals={}
        for j in range(max(0,i-2),min(len(rows),i+3)):
            rr=rows[j]
            for di,c in enumerate(rr):
                name=c['v'].lower()
                if name not in ('carboplatin','paclitaxel') or name in drug_refs:
                    continue
                nums=[x for x in rr[di+1:di+5] if isnum(x['v'])]
                # Drug rows list AUC first and IC50 second; retain IC50.
                if len(nums)>=2:
                    pick=nums[1]
                elif len(nums)==1:
                    pick=nums[0]
                else:
                    continue
                drug_refs[name]=pick['ref']
                drug_vals[name]=fnum(pick['v'])
        if clin is None or len(drug_refs)<2:
            debug.append((page,i+1,oid,'missing',clin,drug_refs))
            continue
        score_spec={'refs':[
            {'calc':'divide','args':[{'ref':drug_refs['carboplatin']},87]},
            {'calc':'divide','args':[{'ref':drug_refs['paclitaxel']},4.1]}
        ],'aggregate':'min'}
        truth_spec={'ref':clin['ref'],'map':{'sensitive':1,'Sensitive':1,'resistant':0,'Resistant':0}}
        records.append({'id':oid,'score':score_spec,'truth':truth_spec})
        pred=min(drug_vals['carboplatin']/87,drug_vals['paclitaxel']/4.1)<1
        truth=clin['v'].lower()=='sensitive'
        debug.append((page,i+1,oid,pred,truth,drug_vals))

# De-duplicate in case a split organoid label is repeated across adjacent extracted rows.
uniq=[]; seen=set()
for r in records:
    if r['id'] not in seen:
        uniq.append(r); seen.add(r['id'])
records=uniq
correct=sum(1 for x in debug if len(x)>=5 and x[3]==x[4] and x[2] in seen)
acc=correct/len(records) if records else None
print('records',len(records),'correct',correct,'accuracy',acc)
for x in debug: print(x)
status='computed' if len(records)==20 and acc is not None and abs(acc-0.8)<=0.005 else 'blocked'
CONTRACT={'status':status,'fields':{'unit':{'value':'organoid_line','evidence':['article:p34'],'explanation':'Twenty organoid drug-screening results were compared with clinical responses to paclitaxel-carboplatin therapy.'},'platform':{'value':'organoid','evidence':['article:p34','article:p35'],'explanation':'The predictions came from patient-derived ovarian tumour organoids.'},'readout':{'value':'ic50','evidence':['article:p34'],'explanation':'IC50 was the primary drug-response readout, with AUC used only as an assisting measure.'},'direction':{'value':'lower_sensitive','evidence':['article:p34','article:p35'],'explanation':'IC50 below the drug-specific Cmax denotes sensitivity, so lower values indicate greater sensitivity.'},'threshold_rule':{'value':'fixed_numeric','evidence':['article:p34'],'explanation':'External Cmax thresholds were 87 µM for carboplatin and 4.1 µM for paclitaxel; sensitivity to either drug predicted TC efficacy.'},'threshold_timing':{'value':'independent_reference','evidence':['article:p34'],'explanation':'The Cmax cutoffs were external pharmacokinetic references rather than thresholds fitted to these patients.'},'patient_mapping':{'value':'individual_available','evidence':['article:p37','article:p34'],'explanation':'Each organoid record was linked to an individually identified patient and clinical response.'},'regimen_match':{'value':'matched','evidence':['article:p34','article:p37'],'explanation':'Paclitaxel/carboplatin assay sensitivity was compared with clinical response to the TC regimen.'},'n_units':{'value':len(records),'evidence':['article:p34','article:p37'],'explanation':'The exact prospective comparison contained 20 screened organoid records.'},'split':{'value':'none','evidence':['article:p34','article:p37'],'explanation':'No cohort-specific model fitting or held-out split was used; fixed external Cmax rules were applied.'}},'headline':{'metric':'accuracy','reported':0.8,'reported_evidence':['article:p3','article:p37'],'threshold':1,'op':'<','score_direction':'lower','records':records,'blocked_reason':None if status=='computed' else 'Could not reconstruct 20 row-level paired organoid IC50 and prospective clinical-response records.'},'notes':['The article names four mismatches (Org-124, Org-137, Org-222, and Org-225), yielding 16/20 = 80%.']}"}
